// Club calendar migrated from the Wix calendar (retrieved 21 November 2026). Source of truth: calendar.json.
// The public feed for other calendar apps is /leeside-calendar.ics, generated by scripts/build-calendar.mjs.
import events from "./calendar.json";

export type CalendarEvent = {
  id: string;
  title: string;
  /** Dublin wall-clock start, e.g. 2025-09-01T18:00 */
  start: string;
  end: string | null;
  timezone: "Europe/Dublin";
  startUtc: string;
  endUtc: string | null;
  venue: string | null;
  address: string | null;
  cancelled: boolean;
  description: string | null;
  source: string;
};

export const CALENDAR_EVENTS = events as CalendarEvent[];
export const CALENDAR_FEED = "/leeside-calendar.ics";

/** Events that have not been cancelled and start after `now`, soonest first. */
export function upcomingEvents(now: number): CalendarEvent[] {
  return CALENDAR_EVENTS.filter((e) => !e.cancelled && Date.parse(e.startUtc) > now).sort(
    (a, b) => Date.parse(a.startUtc) - Date.parse(b.startUtc),
  );
}
